CREATE TABLE d (
  a INT DEFAULT 0,
  b VARCHAR(10) DEFAULT 'x',
  c BOOLEAN DEFAULT TRUE,
  e DATETIME DEFAULT NOW(),
  f DECIMAL(5,2) DEFAULT 1.5,
  g INT DEFAULT NULL,
  h VARCHAR(20) DEFAULT (UUID()),
  i BIT(1) DEFAULT b'1',
  j VARBINARY(4) DEFAULT 0x00FF,
  k TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  l INT UNSIGNED ZEROFILL DEFAULT 007,
  m FLOAT DEFAULT -2.5e3,
  n TEXT NOT NULL,
  o YEAR(4),
  p MEDIUMINT(8) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'it''s a "quote"'
) ENGINE=MyISAM;
